package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamDemocracyBank1 {
  private const val T = "ප්‍රජාතන්ත්‍රවාදය, පුරවැසිභාවය හා ආණ්ඩු ක්‍රම"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("'ප්‍රජාතන්ත්‍රවාදය' යන අරුත දෙන ඉංග්‍රීසි වචනය බිඳී ආ ග්‍රීක පද යුගලය කුමක්ද?", "ඩෙමොස් සහ ක්‍රටෝස්", "පොලිස් සහ නොමොස්", "සිවිස් සහ ලෙක්ස්", "ආර්කේ සහ එතොස්", "ග්‍රීක භාෂාවේ Demos (ජනතාව) සහ Kratos (බලය/පාලනය) එක්වීමෙන් Democracy බිහිවිය."),
    q("'ජනතාවගේ, ජනතාව විසින්, ජනතාව උදෙසා කරනු ලබන පාලනය' ලෙස ප්‍රජාතන්ත්‍රවාදය අර්ථ දැක්වූයේ කවුද?", "ඒබ්‍රහම් ලින්කන්", "තෝමස් ජෙෆර්සන්", "ඇරිස්ටෝටල්", "ජෝන් ලොක්", "1863 ගෙටිස්බර්ග් දේශනයේදී ඇමරිකානු ජනාධිපති ඒබ්‍රහම් ලින්කන් මෙම නිර්වචනය ඉදිරිපත් කළේය."),
    q("පුරාණ ග්‍රීසියේ ඇතැන්ස් නගර රාජ්‍යයේ ක්‍රියාත්මක වූ ප්‍රජාතන්ත්‍රවාදී ආකෘතිය කුමක්ද?", "සෘජු ප්‍රජාතන්ත්‍රවාදය", "නියෝජිත ප්‍රජාතන්ත්‍රවාදය", "පාර්ලිමේන්තු ප්‍රජාතන්ත්‍රවාදය", "ව්‍යවස්ථාපිත රාජාණ්ඩු ක්‍රමය", "පුරවැසියන් සියලු දෙනා එක්රැස් වී සෘජුවම තීරණ ගත් බැවින් එය සෘජු ප්‍රජාතන්ත්‍රවාදය විය."),
    q("වර්තමාන ලෝකයේ සෘජු ප්‍රජාතන්ත්‍රවාදී ලක්ෂණ තවමත් බහුලව භාවිත කරන රට කුමක්ද?", "ස්විට්සර්ලන්තය", "චීනය", "සෞදි අරාබිය", "උතුරු කොරියාව", "ස්විට්සර්ලන්තයේ ජනමත විචාරණ සහ ජනප්‍රිය මුලපිරීම් මඟින් සෘජු ප්‍රජාතන්ත්‍රවාදය ක්‍රියාත්මක වේ."),
    q("විශාල ජනගහනයක් සිටින නූතන රාජ්‍යවල බහුලව ක්‍රියාත්මක වන ප්‍රජාතන්ත්‍රවාදී පාලන ක්‍රමය කුමක්ද?", "නියෝජිත ප්‍රජාතන්ත්‍රවාදය", "සෘජු ප්‍රජාතන්ත්‍රවාදය", "ප්‍රභූතන්ත්‍රවාදය", "ඒකාධිපතිවාදය", "ජනතාව තම නියෝජිතයන් ඡන්දයෙන් පත් කර ඔවුන් මඟින් පාලනය ගෙන යාම නියෝජිත ප්‍රජාතන්ත්‍රවාදයයි."),
    q("ප්‍රජාතන්ත්‍රවාදී රාජ්‍යයක උත්තරීතර බලය හෙවත් පරමාධිපත්‍යය හිමිවන්නේ කාටද?", "මහජනතාවට", "ජනාධිපතිවරයාට", "අග්‍රාමාත්‍යවරයාට", "ශ්‍රේෂ්ඨාධිකරණයට", "ප්‍රජාතන්ත්‍රවාදයේ මූලික පදනම ජනතා පරමාධිපත්‍යයයි."),
    q("ශ්‍රී ලංකා ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ කුමන වගන්තියෙන් ජනතා පරමාධිපත්‍යය පිළිබඳව ප්‍රකාශ වේද?", "3 වන වගන්තිය", "1 වන වගන්තිය", "9 වන වගන්තිය", "18 වන වගන්තිය", "1978 ව්‍යවස්ථාවේ 3 වන වගන්තියෙන් ජනරජයේ පරමාධිපත්‍යය ජනතාව කෙරෙහි පිහිටා ඇති බව දක්වයි."),
    q("ප්‍රජාතන්ත්‍රවාදී තීරණ ගැනීමේදී බහුතර කැමැත්ත ක්‍රියාත්මක වුවද අනිවාර්යයෙන්ම ආරක්ෂා කළ යුත්තේ කුමක්ද?", "සුළුතරයේ අයිතිවාසිකම්", "පාලක පක්ෂයේ බලය", "රාජ්‍ය නිලධාරී වරප්‍රසාද", "ඒකාධිකාරී වෙළඳපොළ", "බහුතර පාලනය තුළ සුළුතර ජන කොටස්වල මූලික අයිතිවාසිකම් සුරැකීම ප්‍රජාතන්ත්‍රවාදයේ මූලධර්මයකි."),
    q("විවිධ දේශපාලන පක්ෂ, මතවාද සහ සංවිධානවලට නිදහසේ ක්‍රියාත්මක වීමට ඇති ඉඩකඩ කුමන නමින් හැඳින්වේද?", "දේශපාලන බහුත්වවාදය", "දේශපාලන මධ්‍යගතකරණය", "ඒකපාක්ෂික ආධිපත්‍යය", "ප්‍රභූවාදය", "විවිධ මත හා පක්ෂ පිළිගැනීම දේශපාලන බහුත්වවාදය (Pluralism) ලෙස හැඳින්වේ."),
    q("ආණ්ඩුවක බලතල ලිඛිත උත්තරීතර නීතියකින් සීමා කර පාලනය පවත්වාගෙන යාමේ සංකල්පය කුමක්ද?", "ආණ්ඩුක්‍රම ව්‍යවස්ථාවාදය", "පරමාධිකාරිත්වය", "රාජාණ්ඩුවාදය", "සමාජවාදය", "ආණ්ඩුක්‍රම ව්‍යවස්ථාවාදය මඟින් පාලකයන්ගේ අත්තනෝමතික බලය සීමා කරයි."),
    q("'එක් පුද්ගලයෙකුට එක් ඡන්දයක්' යන ප්‍රජාතන්ත්‍රවාදී මූලධර්මයෙන් තහවුරු වන්නේ කුමක්ද?", "දේශපාලන සමානාත්මතාව", "ආර්ථික ඒකාධිකාරය", "සමාජ ධූරාවලිය", "පන්ති විෂමතාව", "ධනය, කුලය හෝ තරාතිරම නොසලකා සෑම පුරවැසියෙකුටම සමාන ඡන්ද වටිනාකමක් ලැබේ."),
    q("පාලකයන් සහ රාජ්‍ය නිලධාරීන් තම තීරණ හා ක්‍රියා පිළිබඳව ජනතාවට පිළිතුරු දීමට බැඳී සිටීම කුමක්ද?", "වගවීම", "විමධ්‍යගතකරණය", "රාජ්‍ය මුක්තිය", "නිෂේධ බලය", "මහජන නියෝජිතයන් හා නිලධාරීන් ජනතාවට වගකිව යුතු වීම වගවීම (Accountability) වේ."),
    q("රජයේ වියදම්, ටෙන්ඩර් සහ ප්‍රතිපත්ති තීරණ මහජනතාවට විවෘතව දැනගැනීමට තිබීම කුමන ලක්ෂණයද?", "විනිවිදභාවය", "රහස්‍යභාවය", "ඒකාබද්ධතාව", "ස්වෛරීභාවය", "තීරණ ගැනීමේ ක්‍රියාවලිය විවෘත වීම විනිවිදභාවය (Transparency) ලෙස හැඳින්වේ."),
    q("ප්‍රජාතන්ත්‍රවාදී ආණ්ඩුවක සාමකාමී බල හුවමාරුව සිදුකෙරෙන ප්‍රධානතම මාර්ගය කුමක්ද?", "නිදහස් හා සාධාරණ මැතිවරණ", "හමුදා කුමන්ත්‍රණ", "පරම්පරාගත උරුමය", "ප්‍රචණ්ඩ කැරලි", "නියමිත කාලයට පැවැත්වෙන නිදහස් මැතිවරණ මඟින් ජනතාවට සාමකාමීව පාලකයන් මාරු කළ හැක."),
    q("සෘජු ප්‍රජාතන්ත්‍රවාදය වර්තමාන විශාල ජනගහනයක් සහිත රටවල ප්‍රායෝගික නොවීමට ප්‍රධාන හේතුව කුමක්ද?", "සියලු පුරවැසියන් එකවර රැස්කිරීමේ අපහසුව", "මැතිවරණ නීති නොමැති වීම", "ව්‍යවස්ථාදායකයක් නොපැවතීම", "ජනතාවට අධ්‍යාපනයක් නොමැති වීම", "මිලියන ගණනක් පුරවැසියන් දිනපතා එකම ස්ථානයක රැස්වී තීරණ ගැනීම ප්‍රායෝගිකව කළ නොහැක."),
    q("රාජ්‍යයක අත්‍යවශ්‍ය මූලික අංග හතරට අයත් නොවන්නේ පහත සඳහන් කුමක්ද?", "ඒකාධිපති පාලකයෙකු", "නිශ්චිත භූමියක්", "ස්ථිර ජනගහනයක්", "ස්වෛරීභාවයක්", "රාජ්‍යයක මූලික අංග හතර වන්නේ භූමිය, ජනගහනය, ආණ්ඩුව සහ ස්වෛරීභාවයයි."),
    q("රාජ්‍යයේ මූලික අංග හතර 1933 දී විධිමත්ව අර්ථ දක්වන ලද ජාත්‍යන්තර සම්මුතිය කුමක්ද?", "මොන්ටෙවීඩියෝ සම්මුතිය", "ජිනීවා සම්මුතිය", "වියනා සම්මුතිය", "වර්සේල්ස් ගිවිසුම", "1933 මොන්ටෙවීඩියෝ සම්මුතිය රාජ්‍යයක නිර්ණායක හතර නීතිගත කළේය."),
    q("අභ්‍යන්තර හා බාහිර බලපෑම්වලින් තොරව තීරණ ගැනීමට රාජ්‍යයකට ඇති උත්තරීතර බලය කුමක්ද?", "ස්වෛරීභාවය", "සන්ධීය බලය", "විමධ්‍යගත බලය", "පළාත් ස්වයංපාලනය", "ස්වෛරීභාවය යනු රාජ්‍යයකට අභ්‍යන්තරව හා බාහිරව ඇති පරම බලයයි."),
    q("ආණ්ඩුව සහ රාජ්‍යය අතර ප්‍රධාන වෙනස්කම කුමක්ද?", "රාජ්‍යය ස්ථිර වන අතර ආණ්ඩුව කාලීනව වෙනස් වේ", "ආණ්ඩුව ස්ථිර වන අතර රාජ්‍යය වෙනස් වේ", "දෙකෙහිම කිසිදු වෙනසක් නැත", "රාජ්‍යයට ස්වෛරීභාවයක් නැත", "මැතිවරණවලින් ආණ්ඩු මාරු වුවද රාජ්‍යය අඛණ්ඩව පවතී."),
    q("රාජ්‍යයේ සියලු උත්තරීතර පාලන බලතල එක් මධ්‍යම ආණ්ඩුවක් සතුව පවතින රාජ්‍ය ආකෘතිය කුමක්ද?", "ඒකීය රාජ්‍ය ක්‍රමය", "සන්ධීය රාජ්‍ය ක්‍රමය", "රාජ්‍ය සන්ධාන ක්‍රමය", "කලාපීය සංගම් ක්‍රමය", "ඒකීය රාජ්‍යයක උත්තරීතර ව්‍යවස්ථාදායක බලය මධ්‍යම රජය සතු වේ."),
    q("1978 ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 2 වන වගන්තිය අනුව ශ්‍රී ලංකාව කවර ආකාරයේ රාජ්‍යයක්ද?", "ඒකීය රාජ්‍යයකි", "සන්ධීය රාජ්‍යයකි", "රාජාණ්ඩුවකි", "සංයුක්ත රාජ්‍යයකි", "ව්‍යවස්ථාවේ 2 වන වගන්තියෙන් ශ්‍රී ලංකාව ඒකීය රාජ්‍යයක් බව තහවුරු කරයි."),
    q("මධ්‍යම ආණ්ඩුව සහ ප්‍රාන්ත ආණ්ඩු අතර බලතල ව්‍යවස්ථාවෙන්ම ස්ථිරව බෙදා ඇති රාජ්‍ය ක්‍රමය කුමක්ද?", "සන්ධීය රාජ්‍ය ක්‍රමය", "ඒකීය රාජ්‍ය ක්‍රමය", "ඒකාධිපති ක්‍රමය", "රදළවාදී ක්‍රමය", "සන්ධීය (Federal) රාජ්‍යයක බලය මධ්‍යය හා ප්‍රාන්ත අතර ව්‍යවස්ථාවෙන් බෙදේ."),
    q("පහත සඳහන් රටවල් අතරින් සන්ධීය රාජ්‍ය ක්‍රමයක් ක්‍රියාත්මක වන රට කුමක්ද?", "ඇමරිකා එක්සත් ජනපදය", "ශ්‍රී ලංකාව", "ප්‍රංශය", "ජපානය", "ඇමරිකාව, ඉන්දියාව සහ ඕස්ට්‍රේලියාව සන්ධීය රාජ්‍ය සඳහා ප්‍රකට උදාහරණ වේ."),
    q("පහත සඳහන් රටවල් අතරින් ඒකීය රාජ්‍ය ආකෘතියක් පවතින රටක් වන්නේ කුමක්ද?", "එක්සත් රාජධානිය", "ජර්මනිය", "කැනඩාව", "ස්විට්සර්ලන්තය", "එක්සත් රාජධානිය සහ ශ්‍රී ලංකාව ඒකීය රාජ්‍යයන් ලෙස පවතී."),
    q("විධායකය ව්‍යවස්ථාදායකයෙන් වෙන්ව ජනතාව විසින් සෘජුවම ජනාධිපතිවරයා තෝරාපත් කරගන්නා ආණ්ඩු ක්‍රමය කුමක්ද?", "ජනාධිපති ආණ්ඩු ක්‍රමය", "පාර්ලිමේන්තු ආණ්ඩු ක්‍රමය", "කාරක සභා ආණ්ඩු ක්‍රමය", "රාජාණ්ඩු ක්‍රමය", "ඇමරිකා එක්සත් ජනපදයේ ක්‍රියාත්මක වන පරිදි ජනාධිපති ක්‍රමයේ විධායකය ව්‍යවස්ථාදායකයට වග නොකියයි."),
    q("පාර්ලිමේන්තුවේ බහුතර විශ්වාසය දිනාගන්නා අග්‍රාමාත්‍යවරයා ප්‍රමුඛ කැබිනට් මණ්ඩලය විධායක බලය හොබවන ක්‍රමය කුමක්ද?", "පාර්ලිමේන්තු ආණ්ඩු ක්‍රමය", "ජනාධිපති ආණ්ඩු ක්‍රමය", "පරම රාජාණ්ඩු ක්‍රමය", "හමුදා පාලන ක්‍රමය", "වෙස්ට්මින්ස්ටර් පාර්ලිමේන්තු ක්‍රමය තුළ අගමැති හා කැබිනට්ටුව ව්‍යවස්ථාදායකයට වගකියයි."),
    q("ශ්‍රී ලංකාවේ 1978 ව්‍යවස්ථාව යටතේ ක්‍රියාත්මක වන පාලන ආකෘතිය කුමක්ද?", "අර්ධ-ජනාධිපති ආණ්ඩු ක්‍රමය", "පූර්ණ රාජාණ්ඩු ක්‍රමය", "ඒකපාක්ෂික ක්‍රමය", "සන්ධීය කාරක සභා ක්‍රමය", "ජනාධිපති ක්‍රමයේ හා පාර්ලිමේන්තු ක්‍රමයේ ලක්ෂණ දෙකම ඇති බැවින් එය අර්ධ-ජනාධිපති ක්‍රමයකි."),
    q("ප්‍රංශයේ පස්වන ජනරජයේ පාලන ආකෘතිය අනුසාරයෙන් බිහිවූ පාලන ක්‍රමය කුමක්ද?", "අර්ධ-ජනාධිපති ආණ්ඩු ක්‍රමය", "වෙස්ට්මින්ස්ටර් ක්‍රමය", "සෘජු ඇතැන්ස් ක්‍රමය", "නාමික රාජාණ්ඩු ක්‍රමය", "ප්‍රංශය සහ ශ්‍රී ලංකාව අර්ධ-ජනාධිපති ආණ්ඩු ක්‍රම සඳහා උදාහරණ වේ."),
    q("රටක උත්තරීතර හා නීත්‍යානුකූල සාමාජිකත්වය හිමි තැනැත්තා හඳුන්වන්නේ කුමන නමින්ද?", "පුරවැසියා", "සංචාරකයා", "විදේශිකයා", "තානාපතිවරයා", "රාජ්‍යයකට පක්ෂපාතී වෙමින් සිවිල් හා දේශපාලන අයිතීන් භුක්ති විඳින පුද්ගලයා පුරවැසියා වේ."),
    q("පුරවැසිභාවය හිමිවන ප්‍රධාන නෛතික ආකාර දෙක මොනවාද?", "උපතින් සහ ලියාපදිංචියෙන්", "වත්කමින් සහ අධ්‍යාපනයෙන්", "සංචාරයෙන් සහ රැකියාවෙන්", "පරිත්‍යාගයෙන් සහ ආගමෙන්", "පරම්පරාගත උපත (Jus sanguinis/soli) හෝ නීත්‍යානුකූල ලියාපදිංචිය මඟින් පුරවැසිභාවය ලැබේ."),
    q("විදේශිකයෙකු නීත්‍යානුකූල කොන්දේසි සපුරා රජයෙන් ඉල්ලුම් කර ශ්‍රී ලංකා පුරවැසිභාවය ලබාගැනීම කුමන ක්‍රමයද?", "ලියාපදිංචිය මඟින් පුරවැසිභාවය", "උපතින් පුරවැසිභාවය", "තාවකාලික වීසා බලපත්‍රය", "රාජ්‍ය තාන්ත්‍රික මුක්තිය", "රටක උපත නොලැබුවද නීත්‍යානුකූල සුදුසුකම් සපුරා ලියාපදිංචියෙන් පුරවැසිභාවය ලැබිය හැක."),
    q("යම් පුද්ගලයෙකුට එකවර රටවල් දෙකක නීත්‍යානුකූල පුරවැසිභාවය දැරීමට ඇති අවස්ථාව කුමක්ද?", "ද්විත්ව පුරවැසිභාවය", "අසීමිත වීසා හිමිකම", "රාජ්‍ය රහිතභාවය", "සංක්‍රමණික තත්ත්වය", "රටවල් දෙකක පුරවැසි අයිතිය එකවර දැරීම ද්විත්ව පුරවැසිභාවයයි."),
    q("ශ්‍රී ලංකාවේ 21 වන ආණ්ඩුක්‍රම ව්‍යවස්ථා සංශෝධනය අනුව ද්විත්ව පුරවැසියන්ට පැනවූ සීමාව කුමක්ද?", "පාර්ලිමේන්තු මන්ත්‍රී ධුර දැරීම තහනම් කිරීම", "රටින් පිටවීම තහනම් කිරීම", "පෞද්ගලික දේපළ අහිමි කිරීම", "මූලික අධ්‍යාපනය අත්හිටුවීම", "21 වන සංශෝධනයෙන් ද්විත්ව පුරවැසියන්ට පාර්ලිමේන්තු මන්ත්‍රීවරුන් වීම අවහිර කරන ලදී."),
    q("කිසිදු රාජ්‍යයක නීත්‍යානුකූල පුරවැසිභාවයක් නොමැති පුද්ගලයා හඳුන්වනු ලබන්නේ කුමන නමින්ද?", "රාජ්‍ය රහිත පුද්ගලයා", "ද්විත්ව පුරවැසියා", "සාමාන්‍ය පුරවැසියා", "මහ කොමසාරිස්වරයා", "ලොව කිසිදු රටකින් පුරවැසියෙකු ලෙස නොපිළිගන්නා අය Stateless person ලෙස හැඳින්වේ."),
    q("ශ්‍රී ලංකාවේ ප්‍රථම පුරවැසිභාවය පිළිබඳ පනත සම්මත කරන ලද වර්ෂය කුමක්ද?", "1948", "1931", "1956", "1972", "1948 අංක 18 දරන පුරවැසි පනත මඟින් නිදහස් ලංකාවේ පුරවැසිභාවය නීතිගත කෙරිණි."),
    q("ඉන්දීය සම්භවයක් සහිත වතුකර ජනතාවගේ පුරවැසිභාවය පිළිබඳ ගැටලුව විසඳීමට 1964 දී අත්සන් කළ ගිවිසුම කුමක්ද?", "සිරිමා-ශාස්ත්‍රී ගිවිසුම", "ඉන්දු-ලංකා ගිවිසුම", "බණ්ඩාරනායක-චෙල්වනායගම් ගිවිසුම", "කොළඹ ගිවිසුම", "1964 සිරිමා-ශාස්ත්‍රී ගිවිසුම මඟින් වතුකර ජනතාවට පුරවැසිභාවය ලබාදීමට පියවර ගැනිණි."),
    q("ඉන්දීය සම්භවයක් ඇති ඉතිරි පුද්ගලයන් සියල්ලටම ශ්‍රී ලංකා පුරවැසිභාවය හිමිවූයේ කුමන වසරේ සම්මත පනතින්ද?", "2003", "1987", "1974", "1958", "2003 අංක 35 දරන පනතින් රාජ්‍ය රහිතව සිටි ඉන්දීය සම්භවයක් සහිත ජනතාවට පුරවැසිභාවය හිමිවිය."),
    q("උපත සිදුවූ භූමිය මත පදනම්ව පුරවැසිභාවය ලබාදීමේ නීතිමය මූලධර්මය හඳුන්වන්නේ කෙසේද?", "ජස් සෝලි", "ජස් සැන්ගුයිනිස්", "හබයාස් කෝපස්", "මැන්ඩමුස්", "Jus soli යනු භූමියේ උපත අනුව පුරවැසිභාවය හිමිවීමේ මූලධර්මයයි."),
    q("දෙමාපියන්ගේ ලේ ඥාතිත්වය මත පුරවැසිභාවය තීරණය වීමේ නීතිමය මූලධර්මය කුමක්ද?", "ජස් සැන්ගුයිනිස්", "ජස් සෝලි", "අල්ට්‍රා වයර්ස්", "ප්‍රයිමා ෆේසි", "Jus sanguinis යනු දෙමාපියන්ගේ ජාතිකත්වය අනුව දරුවාට පුරවැසිභාවය හිමිවීමයි."),
    q("යහපත් ප්‍රජාතන්ත්‍රවාදී පුරවැසියෙකු තුළ පැවතිය යුතු මූලිකම සමාජ ගුණාංගය කුමක්ද?", "අන්‍ය මත ඉවසීම හා නීතිගරුක බව", "තම මතය පමණක් බලෙන් පැටවීම", "පොදු දේපළ පෞද්ගලිකව භුක්ති විඳීම", "දේශපාලන උදාසීනතාව දැක්වීම", "අන්‍ය මත ඉවසීම, සංවාදශීලී බව සහ නීතිගරුක බව ප්‍රජාතන්ත්‍රවාදය සුරකියි."),
    q("විරෝධතා දැක්වීමේදී ප්‍රජාතන්ත්‍රවාදී පුරවැසියෙකු අනුගමනය කළ යුතු ක්‍රමවේදය කුමක්ද?", "සාමකාමී හා නීත්‍යානුකූල විරෝධතා", "පොදු දේපළවලට හානි කිරීම", "මහාමාර්ග සම්පූර්ණයෙන් අවහිර කිරීම", "ප්‍රචණ්ඩ ක්‍රියා මෙහෙයවීම", "අන් අයගේ අයිතීන්ට හානි නොවන පරිදි සාමකාමීව රැස්වී විරෝධය පෑම ප්‍රජාතන්ත්‍රවාදී ලක්ෂණයකි."),
    q("ප්‍රජාතන්ත්‍රවාදයේ පැවැත්මට එල්ල වන ප්‍රධානතම අභියෝගයක් වන්නේ කුමක්ද?", "ඡන්ද දූෂණ හා දේශපාලන උදාසීනතාව", "නිදහස් අධ්‍යාපනය ව්‍යාප්ත වීම", "සිවිල් සංවිධාන ක්‍රියාකාරී වීම", "ස්වාධීන අධිකරණ පද්ධතිය", "ඡන්ද දූෂණ, අල්ලස, අන්තවාදය සහ ජනතාව ඡන්දයෙන් ඈත් වීම ප්‍රජාතන්ත්‍රවාදය දුර්වල කරයි."),
    q("අන් අයගේ සමාන නිදහස උල්ලංඝනය නොවන පරිදි තම නිදහස භුක්ති විඳීම පැහැදිලි කරන සංකල්පය කුමක්ද?", "සීමිත හා වගකීම් සහගත නිදහස", "අසීමිත පරම නිදහස", "ඒකාධිපති මුක්තිය", "බලහත්කාරී පාලනය", "මාගේ නිදහස අනෙකාගේ නාසය කෙළවරින් අවසන් වේ යන්නෙන් වගකීම් සහගත නිදහස පැහැදිලි වේ."),
    q("රටක සියලු දෙනා ජීවත් වීමේ අවම ආර්ථික මට්ටමක් ලබාදෙමින් සමාජ සාධාරණත්වය තහවුරු කිරීම කුමක්ද?", "ආර්ථික ප්‍රජාතන්ත්‍රවාදය", "වෙළඳපොළ ඒකාධිකාරය", "රදළ ආර්ථික ක්‍රමය", "යටත්විජිත ආර්ථිකය", "දේශපාලන නිදහසට අමතරව දරිද්‍රතාවයෙන් මිදීම ආර්ථික ප්‍රජාතන්ත්‍රවාදයයි."),
    q("විධිමත් සම්මුතියක් ඔස්සේ බලහත්කාරයෙන් තොරව දේශපාලන තීරණ ගැනීම කුමන ප්‍රවේශයද?", "ප්‍රජාතන්ත්‍රවාදී සංවාදය", "හමුදා නියෝගය", "ඒකපාර්ශ්වික බලහත්කාරය", "රහසිගත කුමන්ත්‍රණය", "සංවාදය හා එකඟතාව ප්‍රජාතන්ත්‍රවාදී සමාජයක ගැටුම් වළක්වයි."),
    q("ඒකාධිපති පාලන ක්‍රමයක (Dictatorship) ප්‍රධාන ලක්ෂණය කුමක්ද?", "එක් පුද්ගලයෙකු හෝ කණ්ඩායමක් අත සියලු බලය පැවතීම", "ස්වාධීන මැතිවරණ කොමිසමක් තිබීම", "බහුපක්ෂ තරගකාරිත්වය තහවුරු කිරීම", "මාධ්‍ය නිදහස උපරිමයෙන් ආරක්ෂා කිරීම", "ඒකාධිපති ක්‍රමයක විපක්ෂ හා අධිකරණ ස්වාධීනත්වය මර්දනය කෙරේ."),
    q("ව්‍යවස්ථාපිත රාජාණ්ඩු ක්‍රමයක (Constitutional Monarchy) රජුගේ හෝ රැජිනගේ බලතලවල ස්වභාවය කුමක්ද?", "ව්‍යවස්ථාවෙන් සීමා වූ නාමික නායකත්වයක් පමණි", "රටේ සියලු නීති තනිව පැනවීම", "පාර්ලිමේන්තු මැතිවරණ අවලංගු කිරීම", "අධිකරණ තීන්දු හිතුමතේ වෙනස් කිරීම", "එක්සත් රාජධානියේ මෙන් රජු නාමික රාජ්‍ය නායකයා වන අතර සැබෑ බලය පාර්ලිමේන්තුව සතුය."),
    q("පහත සඳහන් රටවල් අතරින් ව්‍යවස්ථාපිත රාජාණ්ඩු ක්‍රමයක් පවතින රට කුමක්ද?", "ජපානය", "ඉන්දියාව", "ජර්මනිය", "ප්‍රංශය", "ජපානයේ අධිරාජ්‍යයා නාමික රාජ්‍ය සංකේතය වන අතර අගමැති ප්‍රමුඛ කැබිනට්ටුව පාලනය ගෙන යයි."),
    q("නිදහස් ලංකාවේ පළමු අග්‍රාමාත්‍යවරයා වශයෙන් පත්වූයේ කවුද?", "ඩී.එස්. සේනානායක මහතා", "එස්.ඩබ්ලිව්.ආර්.ඩී. බණ්ඩාරනායක මහතා", "ඩඩ්ලි සේනානායක මහතා", "සර් ජෝන් කොතලාවල මහතා", "1947 මැතිවරණයෙන් පසු ඩී.එස්. සේනානායක මහතා පළමු අග්‍රාමාත්‍යවරයා විය."),
    q("ලෝකයේ ප්‍රථම කාන්තා අග්‍රාමාත්‍යවරිය ලෙස ශ්‍රී ලංකාවෙන් පත්වූයේ කවුද?", "සිරිමාවෝ බණ්ඩාරනායක මැතිණිය", "චන්ද්‍රිකා බණ්ඩාරනායක මැතිණිය", "විමලා විජේවර්ධන මැතිණිය", "ඉන්දිරා ගාන්ධි මැතිණිය", "1960 දී සිරිමාවෝ බණ්ඩාරනායක මැතිණිය ලොව ප්‍රථම කාන්තා අග්‍රාමාත්‍යවරිය බවට පත්වූවාය."),
    q("ශ්‍රී ලංකාවේ ප්‍රථම විධායක ජනාධිපතිවරයා ලෙස පත්වූයේ කවුද?", "ජේ.ආර්. ජයවර්ධන මහතා", "විලියම් ගොපල්ලව මහතා", "ආර්. ප්‍රේමදාස මහතා", "ඩී.බී. විජේතුංග මහතා", "1978 පෙබරවාරි 4 දින ජේ.ආර්. ජයවර්ධන මහතා ප්‍රථම විධායක ජනාධිපති ලෙස දිවුරුම් දුන්නේය."),
    q("1972 ව්‍යවස්ථාව යටතේ ශ්‍රී ලංකාවේ ප්‍රථම නාමික ජනාධිපතිවරයා වූයේ කවුද?", "විලියම් ගොපල්ලව මහතා", "සර් ඔලිවර් ගුණතිලක මහතා", "ජේ.ආර්. ජයවර්ධන මහතා", "ආර්. ප්‍රේමදාස මහතා", "සෝල්බරි ක්‍රමයේ අවසන් අග්‍රාණ්ඩුකාරවරයා වූ විලියම් ගොපල්ලව මහතා 1972 දී ප්‍රථම ජනාධිපති විය."),
    q("ශ්‍රී ලංකාවේ පළමු කාන්තා විධායක ජනාධිපතිවරිය ලෙස තේරී පත්වූයේ කවුද?", "චන්ද්‍රිකා බණ්ඩාරනායක කුමාරතුංග මැතිණිය", "සිරිමාවෝ බණ්ඩාරනායක මැතිණිය", "සිරිමා බණ්ඩාරනායක මැතිණිය", "රොස්මන්ඩ් සේනානායක මැතිණිය", "1994 ජනාධිපතිවරණයෙන් චන්ද්‍රිකා බණ්ඩාරනායක කුමාරතුංග මැතිණිය ජනාධිපතිවරිය වූවාය."),
    q("ජනාධිපතිවරයෙකුගේ සහ පාර්ලිමේන්තුවේ පොදු පරමාර්ථය විය යුත්තේ කුමක්ද?", "ජනතා පරමාධිපත්‍යය නියෝජනය කරමින් මහජන සුබසිද්ධිය සැලසීම", "දේශපාලන විරුද්ධවාදීන් සිරගත කිරීම", "ව්‍යවස්ථාපිත මැතිවරණ කල් දැමීම", "රාජ්‍ය ආදායම පෞද්ගලිකව බෙදාගැනීම", "පාලකයන් ජනතාවගේ භාරකරුවන් ලෙස මහජන යහපත උදෙසා ක්‍රියා කළ යුතුය."),
    q("ජාතික වැදගත්කමක් ඇති පනතක් හෝ ප්‍රශ්නයක් පිළිබඳව සෘජුවම මහජන මතය විමසීමේ ක්‍රමය කුමක්ද?", "ජනමත විචාරණය", "පාර්ලිමේන්තු විවාදය", "කැබිනට් තීරණය", "අමාත්‍යාංශ චක්‍රලේඛය", "ජනමත විචාරණය (Referendum) යනු සෘජු ප්‍රජාතන්ත්‍රවාදයේ නූතන යාන්ත්‍රණයකි."),
    q("තමන් ජීවත් වන ප්‍රදේශයේ පාසල් හා ප්‍රජා සංවර්ධන කටයුතුවලට පුරවැසියන් ස්වේච්ඡාවෙන් දායක වීම කුමක්ද?", "සක්‍රිය පුරවැසි සහභාගීත්වය", "රාජ්‍ය නිලධාරිවාදය", "ව්‍යවස්ථාදායක මුක්තිය", "සංස්කෘතික හුදෙකලාව", "සමාජ යහපත උදෙසා ඉදිරිපත් වීම සක්‍රිය පුරවැසිභාවයේ (Active Citizenship) ලක්ෂණයකි."),
    q("පුරවැසියෙකු රජයට නියමිත බදු ගෙවීම මූලික වශයෙන් කුමක් ලෙස සැලකේද?", "පුරවැසි යුතුකමක්", "දේශපාලන වරප්‍රසාදයක්", "රාජ්‍ය සම්මානයක්", "අනිවාර්ය දඬුවමක්", "රාජ්‍ය සේවා පවත්වාගෙන යාම සඳහා බදු ගෙවීම පුරවැසි වගකීමකි."),
    q("රටේ පොදු දේපළ ආරක්ෂා කිරීම සෑම ශ්‍රී ලාංකික පුරවැසියෙකුගේම යුතුකමක් බව දැක්වෙන්නේ ව්‍යවස්ථාවේ කුමන වගන්තියෙන්ද?", "28 වන වගන්තිය", "12 වන වගන්තිය", "33 වන වගන්තිය", "76 වන වගන්තිය", "1978 ව්‍යවස්ථාවේ 28 වන වගන්තිය මූලික යුතුකම් පිළිබඳව සඳහන් කරයි."),
    q("නියෝජිත ප්‍රජාතන්ත්‍රවාදය සාර්ථක වීමට ජනතාව හා නියෝජිතයන් අතර පැවතිය යුතු මූලික ගුණාංගය කුමක්ද?", "අඛණ්ඩ සන්නිවේදනය හා වගවීම", "නියෝජිතයන් ජනතාවගෙන් ඈත් වීම", "ඡන්දදායකයන් තොරතුරු නොවිමසීම", "විරුද්ධ පක්ෂ අහෝසි කිරීම", "ජනතා අවශ්‍යතා නියෝජිතයන් වෙත යොමු වී ඒවාට වගකිව යුතුය."),
    q("රටේ සියලු පුරවැසියන්ට පාලනයේ බලපෑම් සමානව ක්‍රියාත්මක වන 'නීතියේ පාලනය' ප්‍රජාතන්ත්‍රවාදයේ කුමන කුළුණද?", "නීතියේ ආධිපත්‍යය", "ඒකාධිකාරය", "ප්‍රභූවාදය", "සන්ධීයවාදය", "නීතියේ ආධිපත්‍යය (Rule of Law) ප්‍රජාතන්ත්‍රවාදයේ ප්‍රධාන කුළුණකි."),
    q("'ආණ්ඩුක්‍රම ව්‍යවස්ථාව' යන්නෙහි වඩාත් නිවැරදි අර්ථ දැක්වීම කුමක්ද?", "රාජ්‍ය පාලනයේ ව්‍යුහය, බලතල හා පුරවැසි අයිතීන් දක්වන උත්තරීතර නීතිය", "පොලිස් දෙපාර්තමේන්තුව නිකුත් කරන අභ්‍යන්තර නියෝග", "පළාත් පාලන ආයතනයක වාර්ෂික අයවැය ලේඛනය", "දේශපාලන පක්ෂයක මැතිවරණ ප්‍රකාශනය", "ආණ්ඩුක්‍රම ව්‍යවස්ථාව රටේ සියලු සාමාන්‍ය නීතිවලට ඉහළින් පවතින මූලික නීතියයි."),
    q("ලිඛිත ආණ්ඩුක්‍රම ව්‍යවස්ථාවක් නොමැතිව සම්ප්‍රදායන් හා පාර්ලිමේන්තු පනත් මත පාලනය වන ප්‍රකට රට කුමක්ද?", "එක්සත් රාජධානිය", "ඇමරිකා එක්සත් ජනපදය", "ඉන්දියාව", "ශ්‍රී ලංකාව", "බ්‍රිතාන්‍යය අලිඛිත ආණ්ඩුක්‍රම ව්‍යවස්ථාවක් සහිත රාජ්‍යයකි."),
    q("ප්‍රධාන වශයෙන් ලිඛිත හා දැඩි සංශෝධන ක්‍රමයක් සහිත ආණ්ඩුක්‍රම ව්‍යවස්ථාවක් පවතින රට කුමක්ද?", "ඇමරිකා එක්සත් ජනපදය", "එක්සත් රාජධානිය", "නවසීලන්තය", "ඊශ්‍රායලය", "ඇමරිකානු ව්‍යවස්ථාව ලොව පැරණිතම ලිඛිත දැඩි ව්‍යවස්ථාවකි."),
    q("සාමාන්‍ය පනතක් සම්මත කරන සරල බහුතරයකින්ම වෙනස් කළ හැකි ව්‍යවස්ථාව කුමන නමින් හැඳින්වේද?", "නම්‍යශීලී ව්‍යවස්ථාව", "දෘඪ ව්‍යවස්ථාව", "අලිඛිත සන්ධීය ව්‍යවස්ථාව", "රාජාණ්ඩු නියෝගය", "විශේෂ බහුතරයක් අවශ්‍ය නොවී සංශෝධනය කළ හැකි ව්‍යවස්ථාව නම්‍යශීලී ව්‍යවස්ථාවකි."),
    q("සංශෝධනය කිරීම සඳහා පාර්ලිමේන්තුවේ විශේෂ බහුතරයක් හෝ ජනමත විචාරණයක් අවශ්‍ය වන ව්‍යවස්ථාව කුමක්ද?", "දෘඪ ව්‍යවස්ථාව", "නම්‍යශීලී ව්‍යවස්ථාව", "තාවකාලික ව්‍යවස්ථාව", "ප්‍රාදේශීය ප්‍රඥප්තිය", "ශ්‍රී ලංකාවේ 1978 ව්‍යවස්ථාව වැනි විශේෂ ක්‍රියාපටිපාටියකින් සංශෝධනය කරන ව්‍යවස්ථා දෘඪ ව්‍යවස්ථා වේ."),
    q("ශ්‍රී ලංකාවේ 1978 ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ ස්වරූපය අනුව එය කෙබඳු ව්‍යවස්ථාවක්ද?", "ලිඛිත හා දෘඪ ව්‍යවස්ථාවකි", "අලිඛිත හා නම්‍යශීලී ව්‍යවස්ථාවකි", "සන්ධීය හා නාමික ව්‍යවස්ථාවකි", "රාජාණ්ඩු හා සම්ප්‍රදායික ව්‍යවස්ථාවකි", "වගන්ති සංශෝධනයට 2/3 බහුතරය හා ඇතැම් වගන්තිවලට ජනමත විචාරණය අවශ්‍ය බැවින් එය ලිඛිත දෘඪ ව්‍යවස්ථාවකි."),
    q("ප්‍රජාතන්ත්‍රවාදී රාජ්‍යයක 'සිවිල් සමාජය' (Civil Society) යන්නෙන් අදහස් වන්නේ කුමක්ද?", "රජයෙන් හා වාණිජ අංශයෙන් බැහැරව පොදු යහපතට ක්‍රියා කරන ස්වේච්ඡා සංවිධාන", "අමාත්‍ය මණ්ඩලය හා අමාත්‍යාංශ ලේකම්වරුන්", "ත්‍රිවිධ හමුදාව හා පොලිස් නිලධාරීන්", "විදේශ තානාපති කාර්යාල පමණක්", "ස්වේච්ඡා පුරවැසි සංවිධාන, වෘත්තීය සමිති සහ සමාජ සේවා ආයතන සිවිල් සමාජය සාදයි."),
    q("ජනතාව විසින් තමන් කැමති නියෝජිතයෙකු පත් කළ පසු ඔවුන්ගේ ක්‍රියාකාරිත්වය නිරීක්ෂණය කිරීමේ වගකීම හිමිවන්නේ කාටද?", "පුරවැසියන්ට", "විදේශ ආණ්ඩුවලට", "රහස් පොලිසියට", "හමුදා අංශවලට", "සක්‍රිය පුරවැසියන් ඡන්දයෙන් පසුවද පාලකයන්ගේ වගවීම පිළිබඳ අවදියෙන් සිටිය යුතුය."),
    q("වයස අවුරුදු 18 සම්පූර්ණ වූ ශ්‍රී ලාංකික පුරවැසියන් සියලු දෙනාටම ජාති ආගම් භේදයකින් තොරව ලැබෙන මැතිවරණ අයිතිය කුමක්ද?", "සර්වජන ඡන්ද බලය", "සීමිත ඡන්ද බලය", "වෘත්තීය ඡන්ද බලය", "දේපළ පදනම් ඡන්ද බලය", "කිසිදු සීමාවකින් තොරව සියලු වැඩිහිටි පුරවැසියන්ට හිමිවන ඡන්ද අයිතිය සර්වජන ඡන්ද බලයයි."),
    q("ප්‍රජාතන්ත්‍රවාදී පාලනයක නීති සම්පාදනය කිරීමේදී මහජන මතයට සවන් දීමෙන් ලැබෙන ප්‍රධාන ප්‍රතිලාභය කුමක්ද?", "නීති සඳහා මහජන පිළිගැනීම හා සහයෝගය ලැබීම", "නීති සම්පාදන පිරිවැය ශුන්‍ය වීම", "විරුද්ධ පක්ෂ සම්පූර්ණයෙන් අතුරුදන් වීම", "පාර්ලිමේන්තුව රැස්වීම අනවශ්‍ය වීම", "ජනතා අදහස් සැලකිල්ලට ගැනීමෙන් සමාජ සාමය හා පාලන ස්ථාවරත්වය වැඩි වේ."),
    q("ප්‍රජාතන්ත්‍රවාදී පාලන ක්‍රමයේදී ආණ්ඩුවේ වැරදි ප්‍රසිද්ධියේ විවේචනය කිරීමට හා විකල්ප ප්‍රතිපත්ති ඉදිරිපත් කිරීමට බැඳී සිටින ප්‍රධාන පාර්ශ්වය කවුද?", "පාර්ලිමේන්තු විපක්ෂය", "රාජ්‍ය ආරක්ෂක මණ්ඩලය", "මැතිවරණ ලේකම් කාර්යාලය", "විදේශ තානාපති සංගමය", "විපක්ෂය ආණ්ඩුවේ ක්‍රියා විමසිල්ලට ලක් කරමින් විකල්ප ආණ්ඩුවක් ලෙස ක්‍රියා කරයි."),
    q("ප්‍රජාතන්ත්‍රවාදී පාලනයක රාජ්‍ය නායකයාද ඇතුළුව සෑම පුරවැසියෙකුම සමානව යටත් විය යුත්තේ කුමකටද?", "රටේ නීතියට", "පාලක පක්ෂයේ ප්‍රතිපත්තිවලට", "බලවත් ව්‍යාපාරිකයන්ට", "හමුදා නියෝගවලට", "නීතියට ඉහළින් කිසිවෙකු නොසිටීම නීතියේ ආධිපත්‍යයේ හරයයි."),
    q("1978 ව්‍යවස්ථාවේ කුමන වගන්තියෙන් පුරවැසියන්ට තම පරමාධිපත්‍යය ක්‍රියාත්මක කරන ආකාරය දක්වා ඇත්ද?", "4 වන වගන්තිය", "2 වන වගන්තිය", "10 වන වගන්තිය", "15 වන වගන්තිය", "4 වන වගන්තියෙන් ව්‍යවස්ථාදායක, විධායක, අධිකරණ බලතල හා ඡන්ද බලය හරහා පරමාධිපත්‍යය ක්‍රියාත්මක වන අයුරු දක්වයි."),
    q("ශ්‍රී ලංකාවේ ජාතික ධජය, ජාතික ගීය සහ රාජ්‍ය ලාංඡනය පිළිබඳ විධිවිධාන ඇතුළත් වන්නේ කුමන ලේඛනයේද?", "ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ", "දණ්ඩ නීති සංග්‍රහයේ", "මහජන ආරක්ෂක පනතේ", "පළාත් පාලන ආඥා පනතේ", "1978 ව්‍යවස්ථාවේ 6 සහ 7 වගන්තිවලින් ජාතික ධජය හා ගීය පිළිබඳ දැක්වේ."),
    q("පුරවැසියෙකු තම මූලික අයිතිවාසිකම් ඉල්ලා සිටීමේදී ඒ හා සමගාමීව ඉටු කිරීමට බැඳී සිටින්නේ කුමක්ද?", "සමාජ යුතුකම් හා වගකීම්", "පෞද්ගලික ව්‍යාපාරික ලාභ", "පක්ෂ දේශපාලන උද්ඝෝෂණ", "විදේශ ගමන් බලපත්‍ර නීති", "අයිතිවාසිකම් හා යුතුකම් කාසියක දෙපැත්ත මෙන් එකිනෙකට බැඳී පවතී."),
    q("ඒකාබද්ධ රාජ්‍ය සංකල්පය යටතේ රාජ්‍යයන් කිහිපයක් එක්ව පොදු අරමුණක් සඳහා ගිවිසුමකින් සාදාගන්නා ලිහිල් සංගමය කුමක්ද?", "රාජ්‍ය සන්ධානය", "ඒකීය රාජ්‍යය", "ව්‍යවස්ථාපිත අධිරාජ්‍යය", "මහා නගර සභාව", "Confederation හෙවත් රාජ්‍ය සන්ධානයක සාමාජික රාජ්‍යයන් තම ස්වෛරීභාවය රැකගෙන පොදු කටයුතු කරයි."),
    q("මහජන සුබසිද්ධිය සඳහා රජයේ නිලධාරීන් සතු මහජන මුදල් හා බලය අවංකව භාවිත කිරීමේ නෛතික බැඳීම කුමක්ද?", "විශ්වාසභාර වගකීම", "පාර්ලිමේන්තු වරප්‍රසාදය", "රාජ්‍ය මුක්තිය", "නිෂේධ බලය", "පාලකයන් ජනතාවගේ විශ්වාසය මත බලය දරන භාරකරුවන් වීම Fiduciary duty වේ."),
    q("ලෝකයේ සාර්ථක නියෝජිත ප්‍රජාතන්ත්‍රවාදයක් පවත්වාගෙන යාම සඳහා දේශපාලන පක්ෂ කිහිපයක් පැවතීම වැදගත් වන්නේ ඇයි?", "ඡන්දදායකයන්ට විකල්ප ප්‍රතිපත්ති තෝරාගැනීමට ඉඩ ලැබෙන බැවින්", "මැතිවරණ පැවැත්වීම නතර කළ හැකි බැවින්", "අධිකරණ තීන්දු වෙනස් කළ හැකි බැවින්", "රාජ්‍ය සේවය අහෝසි කළ හැකි බැවින්", "බහුපක්ෂ ක්‍රමය මඟින් පාලක පක්ෂය පාලනය කිරීමටත් ජනතාවට විකල්ප තෝරාගැනීමටත් අවස්ථාව ලැබේ."),
    q("ජාතික අභිමානය හා පුරවැසි එකමුතුකම පිළිබිඹු කරන ප්‍රධාන රාජ්‍ය සංකේත තුන කවරේද?", "ජාතික ධජය, ජාතික ගීය සහ රාජ්‍ය ලාංඡනය", "කැබිනට් මණ්ඩලය, පොලිසිය සහ බැංකු", "පළාත් සභා, නගර සභා සහ සමථ මණ්ඩල", "විශ්වවිද්‍යාල, පාසල් සහ ක්‍රීඩා සමාජ", "ආණ්ඩුක්‍රම ව්‍යවස්ථාවෙන් රාජ්‍යයේ ප්‍රධාන සංකේත පිළිගෙන ඇත."),
    q("විධායක බලතල හිමි ජනාධිපතිවරයෙකුගේ පාලනයට සාපේක්ෂව පාර්ලිමේන්තු ආණ්ඩු ක්‍රමයක ප්‍රධාන වාසිය කුමක්ද?", "විධායකය පාර්ලිමේන්තුවට සෘජුව වගකීම", "මැතිවරණ කිසිදා නොපැවැත්වීම", "ජනාධිපතිවරයා අධිකරණය පාලනය කිරීම", "විපක්ෂයක් නොමැති වීම", "කැබිනට් මණ්ඩලය පාර්ලිමේන්තුවෙන් තේරී පත්වී එයට දෛනිකව වගකියයි."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක පුරවැසියෙකු පොදු ස්ථානවලදී අනුගමනය කළ යුතු යහපත් ආකල්පය කුමක්ද?", "පොදු දේපළ සුරැකීම හා පිරිසිදුකම රැකීම", "වීදි ලාම්පු හා බස් නැවතුම් විනාශ කිරීම", "නීති රීති උල්ලංඝනය කර ගමන් කිරීම", "පරිසරයට ප්ලාස්ටික් අපද්‍රව්‍ය දැමීම", "රජයේ හා පොදු සම්පත් මහජන මුදලින් නඩත්තු වන බැවින් ඒවා රැකගැනීම පුරවැසි වගකීමකි."),
    q("පුරාණ ශ්‍රී ලංකාවේ ග්‍රාමීය මට්ටමින් ප්‍රජාතන්ත්‍රවාදී සහභාගීත්ව ලක්ෂණ දක්නට ලැබුණු ආයතනය කුමක්ද?", "ගම්සභාව", "රාජ්‍ය මන්ත්‍රණ සභාව", "සෙනෙට් සභාව", "ව්‍යවස්ථාදායක සභාව", "පුරාණ ගම්සභා ක්‍රමය මඟින් ගමේ වැව් අමුණු හා ආරවුල් ගැමියන්ගේ සහභාගීත්වයෙන් විසඳන ලදී."),
    q("රටක පුරවැසියන්ට වයස, ස්ත්‍රී පුරුෂ භාවය හෝ ජාතිය නොසලකා සමාන අධ්‍යාපන හා සෞඛ්‍ය අවස්ථා සැලසීම කුමන අයිතියට සම්බන්ධද?", "සමාජ සාධාරණත්වය", "ප්‍රභූ වරප්‍රසාදය", "අධිකාරිවාදය", "දේශපාලන මුක්තිය", "සැමට සමාන අවස්ථා සැලසීම සමාජ සාධාරණත්වය තහවුරු කරයි."),
    q("1978 ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 1 වන වගන්තිය අනුව ශ්‍රී ලංකාව හඳුන්වනු ලබන නිල නාමය කුමක්ද?", "ශ්‍රී ලංකා ප්‍රජාතාන්ත්‍රික සමාජවාදී ජනරජය", "ශ්‍රී ලංකා නිදහස් ස්වෛරී ජනරජය", "ලංකා ඩොමීනියන් රාජ්‍යය", "ශ්‍රී ලංකා සන්ධීය ජනරජය", "1978 ව්‍යවස්ථාවේ 1 වන වගන්තිය අනුව නිල නාමය ශ්‍රී ලංකා ප්‍රජාතාන්ත්‍රික සමාජවාදී ජනරජයයි."),
    q("1972 ව්‍යවස්ථාවේ 1 වන වගන්තිය යටතේ රට හඳුන්වන ලද නිල නාමය කුමක්ද?", "ශ්‍රී ලංකා නිදහස් ස්වෛරී ස්වාධීන ජනරජය", "ශ්‍රී ලංකා ප්‍රජාතාන්ත්‍රික සමාජවාදී ජනරජය", "බ්‍රිතාන්‍ය ලංකා කොමසාරිස් පාලනය", "මහනුවර රාජධානිය", "1972 මැයි 22 දින සිට නිදහස් ස්වෛරී ජනරජයක් බවට පත්විය."),
    q("ව්‍යවස්ථාවක 'පූර්විකාව' (Preamble) මඟින් ප්‍රධාන වශයෙන් ප්‍රකාශයට පත් කෙරෙන්නේ කුමක්ද?", "ව්‍යවස්ථාවේ මූලික අරමුණු හා ජාතික දැක්ම", "විශ්‍රාම වැටුප් ගෙවන දින වකවානු", "විදේශ විනිමය අනුපාත වගු", "පාසල් නිවාඩු කාලසටහන", "ආණ්ඩුක්‍රම ව්‍යවස්ථාව සම්මත කිරීමේ පසුබිම හා මූලික අභිමතාර්ථ පූර්විකාවෙන් දැක්වේ."),
    q("යම් රටක ආණ්ඩුව ක්‍රියාත්මක කිරීමේදී මහජන මුදල් අරපිරිමැස්මෙන් භාවිත කිරීම කෙරෙහි බලපාන යහපත් ප්‍රජාතන්ත්‍රවාදී මූලධර්මය කුමක්ද?", "රාජ්‍ය මූල්‍ය වගවීම", "හදිසි නීති බලය", "ඒකාධිපති ආඥාව", "රාජ්‍ය තාන්ත්‍රික වරප්‍රසාදය", "මහජන බදු මුදල් නාස්තියෙන් තොරව වැය කිරීම වගවීමේ ප්‍රධාන කොටසකි."),
    q("ව්‍යවස්ථාදායක බලය සහ විධායක බලය එකම පුද්ගලයෙකු අත පැවතුණහොත් සිදුවිය හැකි ප්‍රධාන අවදානම කුමක්ද?", "පාලනය ඒකාධිපතිත්වයට හැරී පුරවැසි නිදහස අහිමි වීම", "මැතිවරණ පැවැත්වීමේ වේගය දෙගුණ වීම", "රාජ්‍ය ආදායම ස්වයංක්‍රීයව ඉහළ යාම", "අධිකරණ ස්වාධීනත්වය වර්ධනය වීම", "බලය ඒකරාශී වීම අත්තනෝමතික පාලනයකට මඟ පාදයි."),
    q("ශ්‍රී ලංකාවේ පවතින ජනාධිපති ආණ්ඩු ක්‍රමය සහ පාර්ලිමේන්තු ආණ්ඩු ක්‍රමය අතර වෙනස කුමක්ද?", "ජනාධිපති සෘජු ඡන්දයෙන් පත්වන අතර අගමැති පාර්ලිමේන්තුවෙන් පත්වීම", "දෙදෙනාම විදේශ රටකින් පත් කිරීම", "අගමැති සෘජු ජනාධිපතිවරණයෙන් පත් කිරීම", "ජනාධිපති ශ්‍රේෂ්ඨාධිකරණයෙන් පත් කිරීම", "විධායක ජනාධිපතිවරයා රටේම ජනතාවගේ ඡන්දයෙන් පත්වේ."),
    q("කිසියම් පුද්ගලයෙකු රටේ සිවිල් නීතියට වඩා ඉහළින් නොසිටින බව ප්‍රකාශ කළ ප්‍රකට ඉංග්‍රීසි නීතිවේදියා කවුද?", "ඒ.වී. ඩයිසි", "තෝමස් මෝර්", "ජෙරමි බෙන්තම්", "හෙන්රි ස්ටීල් ඕල්කට්", "මහාචාර්ය ඒ.වී. ඩයිසි නීතියේ ආධිපත්‍යය (Rule of Law) පිළිබඳ මූලධර්ම ඉදිරිපත් කළේය."),
    q("ප්‍රජාතන්ත්‍රවාදය තුළ 'සමානාත්මතාව' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "නීතිය ඉදිරියේ සහ සමාජ අවස්ථාවන්හිදී සැමට සමානව සැලකීම", "සියලු දෙනාගේ ශරීර ප්‍රමාණය සමාන වීම", "සියලු දෙනාට එකම රැකියාවක් ලබාදීම", "සියලු දේපළ රජයට පවරා ගැනීම", "ජාති, ආගම්, කුල, ස්ත්‍රී පුරුෂ භේදයකින් තොරව සමාන ගෞරවය හා අවස්ථා හිමිවීමයි."),
    q("ලෝකයේ සම්පූර්ණ ස්වෛරීභාවය හිමි රාජ්‍යයකට සමීපව නොපවතින තත්ත්වය කුමක්ද?", "යටත්විජිත තත්ත්වය", "නිදහස් ජනරජ තත්ත්වය", "ඒකීය ජාතික රාජ්‍යය", "සන්ධීය ප්‍රජාතන්ත්‍රවාදී රාජ්‍යය", "යටත්විජිතයක් වෙනත් විදේශ බලවතෙකුගේ පාලනයට යටත් බැවින් ස්වෛරී නොවේ."),
    q("සාමකාමී බහුතර පාලනයක් යටතේ සුළුතර පක්ෂවලට රජය විවේචනය කිරීමට ඇති ඉඩකඩ කුමක් සඳහා අත්‍යවශ්‍ය වේද?", "ප්‍රජාතන්ත්‍රවාදී සමතුලිතතාව රැකීමට", "රජයේ මුදල් අවභාවිත කිරීමට", "ආණ්ඩුක්‍රම ව්‍යවස්ථාව අහෝසි කිරීමට", "මැතිවරණ පැවැත්වීම නතර කිරීමට", "විරුද්ධ මතයට ඉඩ දීම පාලකයන් වැරදි මඟ යාම වළක්වයි."),
    q("පුරවැසියෙකු පොදු සේවාවක් ලබාගැනීමේදී තම වාරය එනතුරු පෝලිමේ රැඳී සිටීමෙන් පිළිබිඹු වන්නේ කුමක්ද?", "සමාජ විනය හා පුරවැසි ගරුත්වය", "දේශපාලන බියගුලුකම", "රාජ්‍ය සේවා ප්‍රමාදය", "ව්‍යවස්ථා උල්ලංඝනය", "සරල එදිනෙදා ක්‍රියාවලින් පුරවැසි විනය හා අන් අයට ගරු කිරීම ප්‍රකට වේ."),
    q("දේශපාලන උදාසීනතාව හේතුවෙන් පුරවැසියන් ඡන්දය ප්‍රකාශ කිරීමෙන් වැළකී සිටීම නිසා ඇතිවන අහිතකර ප්‍රතිඵලය කුමක්ද?", "නුසුදුසු හා වගවීමෙන් තොර පාලකයන් පත්වීම", "මැතිවරණ වියදම් සම්පූර්ණයෙන් ඉතිරි වීම", "රටේ ආර්ථික වර්ධනය ඉහළ යාම", "නව පාසල් හා රෝහල් ඉදිවීම", "වගකිවයුතු පුරවැසියන් ඡන්දය භාවිත නොකළහොත් ජනතා මතය විකෘති වේ."),
    q("ශ්‍රී ලංකාවේ ජාතික ගීය රචනා කරන ලද්දේ කවුරුන් විසින්ද?", "ආනන්ද සමරකෝන් මහතා", "මහගමසේකර මහතා", "මුනිදාස කුමාරතුංග මහතා", "පණ්ඩිත් අමරදේව මහතා", "'ශ්‍රී ලංකා මාතා' ජාතික ගීය ආනන්ද සමරකෝන් මහතා විසින් රචනා කර තනු නිර්මාණය කෙරිණි."),
    q("ශ්‍රී ලංකාවේ ජාතික ධජයේ කොළ සහ තැඹිලි පැහැති සිරස් තීරු දෙකෙන් නියෝජනය කෙරෙන්නේ කුමක්ද?", "දෙමළ හා මුස්ලිම් ප්‍රජාවන්", "මධ්‍යම කඳුකරය හා මුහුදු තීරය", "කෘෂිකර්මාන්තය හා ධීවර කර්මාන්තය", "ව්‍යවස්ථාදායකය හා විධායකය", "තැඹිලි හා කොළ තීරුවලින් ශ්‍රී ලංකාවේ දෙමළ හා මුස්ලිම් ප්‍රජාවන් නියෝජනය වේ."),
    q("ජාතික ධජයේ සතර කොනේ ඇති බෝපත් හතරෙන් සංකේතවත් කෙරෙන උතුම් ගුණාංග හතර මොනවාද?", "මෙත්තා, කරුණා, මුදිතා, උපේක්ෂා", "සත්‍යය, යුක්තිය, වගවීම, නිදහස", "ධනය, බලය, කීර්තිය, ප්‍රඥාව", "කෘෂිකර්මය, කර්මාන්ත, වෙළඳාම, සේවා", "බෝපත් හතර සතර බ්‍රහ්ම විහරණ සංකේතවත් කරයි."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක පාසල් සිසුවෙකුට ප්‍රජාතන්ත්‍රවාදී පුරුදු පුහුණු වීමට ඇති හොඳම පාසල් ව්‍යුහය කුමක්ද?", "ශිෂ්‍ය පාර්ලිමේන්තුව හා පන්ති කවය", "පෞද්ගලික උපකාරක පන්ති", "වාණිජ වෙළඳසැල්", "විභාග ප්‍රශ්න පත්‍ර මුද්‍රණාල", "ශිෂ්‍ය පාර්ලිමේන්තු මඟින් ඡන්දය, විවාද හා නායකත්වය පුහුණු කෙරේ."),
    q("නීති සම්පාදනයේදී හා පාලනයේදී ස්ත්‍රී පුරුෂ දෙපාර්ශ්වයටම සමානව සහභාගී වීමට අවස්ථාව සැලසීම කුමක්ද?", "ස්ත්‍රී පුරුෂ සමාජභාවීය සමානාත්මතාව", "පීතෘ මූලික ආධිපත්‍යය", "පාරම්පරික කුල ක්‍රමය", "සංස්කෘතික හුදෙකලාව", "පුරවැසියන් සැමට සමාන දේශපාලන නියෝජනය හිමිවිය යුතුය."),
    q("ප්‍රජාතන්ත්‍රවාදී ආණ්ඩුවක ව්‍යවස්ථාපිත සීමාවන් ඉක්මවා ක්‍රියා කරන විට පුරවැසියාට ආරක්ෂාව සලසන ආයතනය කුමක්ද?", "ස්වාධීන අධිකරණය", "වෙළඳ සංගමය", "රාජ්‍ය මුද්‍රණාලය", "විදේශ සේවා කාර්යාංශය", "ව්‍යවස්ථානුකූල සීමා ඉක්මවීම වැළැක්වීම ස්වාධීන අධිකරණයේ වගකීමයි."),
    q("මැතිවරණයකින් තෝරාපත් වූ මන්ත්‍රීවරයෙකු තම මැතිවරණ බලප්‍රදේශයේ ජනතාවට වගකිව යුතු ආකාරය කුමක්ද?", "ජනතා අවශ්‍යතා පාර්ලිමේන්තුවේදී නියෝජනය කිරීම", "ප්‍රතිවිරුද්ධ පක්ෂ කාර්යාල වසා දැමීම", "අධිකරණ තීන්දු අවලංගු කිරීම", "මුදල් නෝට්ටු අච්චු ගැසීම", "මහජන නියෝජිතයන් ජනතාවගේ හඬ ව්‍යවස්ථාදායකයට ගෙන යා යුතුය."),
    q("රටක පුරවැසියන්ට ආණ්ඩුවේ වැඩපිළිවෙළ පිළිබඳව නිවැරදි තොරතුරු ලබාගැනීමට ඉඩ තිබීමෙන් තහවුරු වන්නේ කුමක්ද?", "දැනුවත් ඡන්දදායක සමාජයක් බිහිවීම", "රාජ්‍ය රහස් විදේශවලට විකිණීම", "මැතිවරණ අනවශ්‍ය වීම", "ජනමාධ්‍ය ආයතන වැසී යාම", "නිවැරදි තොරතුරු ඇති විට පුරවැසියන්ට බුද්ධිමත් තීරණ ගත හැක."),
    q("ජනාධිපති ක්‍රමය සහ පාර්ලිමේන්තු ක්‍රමය යන දෙකම ප්‍රජාතන්ත්‍රවාදී ලෙස සැලකෙන්නේ ඇයි?", "පාලකයන් ජනතා ඡන්දයෙන් පත්වී ආණ්ඩුක්‍රම ව්‍යවස්ථාවට යටත්ව ක්‍රියා කරන බැවින්", "රාජාණ්ඩු පරම්පරාවලින් පාලකයන් පත්වන බැවින්", "හමුදා ප්‍රධානීන් අගමැති වන බැවින්", "තනි පක්ෂයක් පමණක් පවතින බැවින්", "දෙකෙහිම මූලික පදනම ජනතා පරමාධිපත්‍යය හා නීතියේ ආධිපත්‍යයයි."),
    q("සෘජු ප්‍රජාතන්ත්‍රවාදයේ නූතන උපකරණයක් ලෙස ජනතාවට නව නීතියක් යෝජනා කිරීමට ඉඩ දෙන ක්‍රමය කුමක්ද?", "ජනප්‍රිය මුලපිරීම", "කැබිනට් සංදේශය", "රාජ්‍ය ලේකම් නියෝගය", "පොලිස් චක්‍රලේඛය", "ස්විට්සර්ලන්තයේ භාවිත වන Popular Initiative මඟින් පුරවැසියන්ට නීති යෝජනා කළ හැක."),
    q("ඡන්දදායකයන් විසින් පත් කළ නියෝජිතයෙකු අකාර්යක්ෂම නම් නිල කාලය අවසන් වීමට පෙර ඉවත් කිරීමේ සෘජු ප්‍රජාතන්ත්‍රවාදී ක්‍රමය කුමක්ද?", "ආපසු කැඳවීමේ බලය", "ජනාධිපති සමාව", "හදිසි නීති ආඥාව", "රාජ්‍ය මුක්තිය", "Recall හෙවත් ආපසු කැඳවීම මඟින් ජනතාවට අකාර්යක්ෂම නියෝජිතයන් ඉවත් කළ හැක."),
    q("ශ්‍රී ලංකාවේ ද්විත්ව පුරවැසිභාවය ලබාදීමේ නෛතික බලය පැවරී ඇත්තේ කුමන පනත යටතේද?", "1948 පුරවැසි පනත සංශෝධන යටතේ", "1833 කෝල්බෲක් ප්‍රතිසංස්කරණ යටතේ", "1988 සමථ මණ්ඩල පනත යටතේ", "2003 පාරිභෝගික පනත යටතේ", "1987 අංක 45 දරන පුරවැසි (සංශෝධන) පනතින් ද්විත්ව පුරවැසිභාවය හඳුන්වා දෙන ලදී."),
    q("පුරවැසියන්ට නීතිමය රැකවරණය සැලසීම රාජ්‍යයේ මූලික කාර්යයක් වන්නේ කුමන සංකල්පය අනුවද?", "සමාජ ගිවිසුම් න්‍යාය", "යටත්විජිත න්‍යාය", "ප්‍රභූ ආධිපත්‍ය න්‍යාය", "ඒකාධිකාරී න්‍යාය", "තෝමස් හොබ්ස්, ජෝන් ලොක් හා රූසෝගේ සමාජ ගිවිසුම් න්‍යාය අනුව රාජ්‍යය බිහිවූයේ පුරවැසි ආරක්ෂාව සඳහාය.")
  )
